# -*- coding: utf-8 -*-
# Giro AI (2026-10-27): genera GEOTERMIA_BASSA_ENTALPIA_PACK (12 schede, L2-L3,
# FACOLTA_IMPIANTI_ENERGIA) — geotermia a bassa entalpia avanzata: sonde, TRT,
# pali energetici, open loop, bilanciamento termico, autorizzazioni, economia, cantiere.
# NON ridondante con RINNOVABILI_IDRO_BIOMASSA_GEOTERMIA_PACK (unica scheda di panorama).
import json, io, os

BASE = r'UNIVERSITA_EDILIZIA/GEOTERMIA_BASSA_ENTALPIA_PACK'
os.makedirs(os.path.join(BASE, 'schede'), exist_ok=True)

KEYS = ['categoria','nome','descrizione','tecnologia','applicazioni','vantaggi','limiti',
        'costi_e_economia','casi_real_world','normative','note_cantiere']

S = []
def add(**kw):
    assert list(kw.keys()) == KEYS, list(kw.keys())
    assert kw['costi_e_economia'].startswith('Ordini di grandezza indicativi: '), kw['nome']
    S.append(kw)

add(
 categoria="Fondamenti",
 nome="La geotermia a bassa entalpia: il sottosuolo come sorgente e volano termico",
 descrizione="Sotto i primi metri di terreno la temperatura si stabilizza intorno a valori prossimi alla media annua dell'aria del luogo (in Italia tipicamente 10-14 C oltre i 10-15 m di profondita'). La geotermia a bassa entalpia usa questa riserva stabile come sorgente invernale e come pozzo di scarico estivo per una pompa di calore: non estrae calore 'geologico', scambia con un volano immenso e gratuito.",
 tecnologia="Principi fisici: onda termica stagionale che si attenua con la profondita' (a 10-15 m l'escursione e' quasi nulla); gradiente geotermico medio circa 3 C ogni 100 m (irrilevante ai fini della bassa entalpia: conta la stabilita', non il gradiente); la pompa di calore geotermica lavora con sorgente a 8-16 C tutto l'anno invece dell'aria esterna a -5/+35 C: di qui la superiorita' stagionale; scambiatori di terreno: sonde verticali (circuito chiuso con fluido termovettore), collettori orizzontali, pali energetici, oppure circuito aperto su acqua di falda; il terreno e' anche accumulo: il calore scaricato d'estate puo' essere parzialmente recuperato d'inverno se il campo e' bilanciato; grandezze chiave: conducibilita' termica del terreno (W/mK), capacita' termica volumica, portata e temperatura del fluido, resistenza termica del foro.",
 applicazioni="Riscaldamento e raffrescamento di edifici residenziali, terziari e scolastici; produzione di acqua calda sanitaria; climatizzazione di serre e piscine; deumidificazione con pre-trattamento geotermico dell'aria; integrazione in edifici NZEB.",
 vantaggi="Sorgente stabile: prestazioni stagionali superiori e costanti anche nelle settimane piu' fredde (quando l'aerotermia rende meno); nessuna unita' esterna (zero rumore, zero impatto visivo, zero vincoli paesaggistici sulla macchina); durata degli scambiatori interrati 50+ anni; raffrescamento estivo diretto quasi gratuito (free cooling) dove il sistema lo consente.",
 limiti="Investimento iniziale piu' alto dell'aerotermia (il campo sonde pesa); serve terreno disponibile o fondazioni da sfruttare; il terreno si esaurisce termicamente se il campo e' mal dimensionato (deriva pluriennale); autorizzazioni e tutele sulle acque sotterranee da verificare prima di progettare; il risparmio si misura in anni, non in mesi.",
 costi_e_economia="Ordini di grandezza indicativi: il sovraccosto del lato geotermico rispetto a una pompa di calore aria-acqua equivalente e' tipicamente 8-20 k€ su un edificio residenziale (campo sonde), ripagato in 7-15 anni dal miglior rendimento stagionale; il free cooling estivo puo' azzerare i consumi di raffrescamento del compressore.",
 casi_real_world="Caso tipo: villa unifamiliare di 180 m2 in zona climatica E con tre sonde verticali da 100 m e pompa di calore da 10 kW su radiante: temperatura di mandata invernale 30-35 C, sorgente mai sotto i 7 C in dieci anni di monitoraggio, raffrescamento estivo in free cooling con solo circolatore.",
 normative="D.Lgs 28/2011 (fonti rinnovabili: la geotermia a bassa entalpia con pompa di calore rientra tra le FER e concorre agli obblighi di integrazione per edifici nuovi e ristrutturazioni rilevanti); serie UNI/TS 11300 per il calcolo delle prestazioni energetiche con rinnovabili; D.Lgs 152/2006 per la tutela delle acque sotterranee; norme regionali per l'esercizio degli scambiatori (da verificare sullo strumento locale).",
 note_cantiere="La geotermia a bassa entalpia non e' 'il calore della Terra': e' la STABILITA' della Terra. Chi promette temperature di sorgente piu' alte della media annua locale sta vendendo aria: chiedi il dato di temperatura indisturbata del sito e usalo nel dimensionamento."
)

add(
 categoria="Indagini",
 nome="Conducibilita' termica del terreno e TRT: dimensionare su dati misurati, non su tabelle",
 descrizione="La resa di un campo sonde dipende da un numero: la conducibilita' termica del terreno. Le tabelle danno ordini di grandezza; il progetto serio si fa su misura in sito. Il Thermal Response Test (TRT) su una sonda pilota e' lo standard di fatto per i campi oltre la taglia domestica.",
 tecnologia="Conducibilita' termica tipiche (ordini di grandezza, W/mK): sabbia secca 0,3-0,8; sabbia satura d'acqua 1,5-2,5; argilla 1,1-2,4; ghiaia satura 1,8-2,5; rocce sedimentarie 1,5-3,0; rocce cristalline 2,5-4,0; l'acqua di falda in movimento migliora di molto lo scambio (advezione); il TRT: si perfora una sonda pilota, si immette potenza termica costante (tipicamente 3-9 kW per 48-72 ore) e si registra la risposta in temperatura del fluido: dall'elaborazione (metodo della linea sorgente o modelli numerici) si ricavano conducibilita' efficace del volume indagato e resistenza termica del foro; dalla conducibilita' si ricava la resa specifica estraibile (W/m di sonda) e quindi i metri di perforazione necessari; prove complementari: carotaggi o stratigrafie del foro pilota, temperatura indisturbata misurata prima del test, eventuale prova in falda per sistemi aperti; per taglie domestiche piccole (1-2 sonde) il TRT puo' costare piu' del beneficio: si usa prudenza sulle tabelle e margine di sicurezza.",
 applicazioni="Ogni campo sonde oltre le 3-4 sonde; edifici terziari, scolastici, sanitari; campi con uso dominante in raffrescamento; verifica di progetti ereditati senza dati di terreno; contenziosi su campi sottodimensionati.",
 vantaggi="Il TRT elimina l'incertezza principale del progetto: i metri di sonda si comprano una volta sola; documenta la resistenza del foro (cementazione fatta bene o male: si vede nel test); produce un referto difendibile in sede di collaudo e di contenzioso.",
 limiti="Costo fisso non banale per le piccole taglie; il TRT misura il volume intorno alla sonda pilota: eterogeneita' del terreno su distanze di decine di metri resta un rischio (piu' sonde pilota su campi grandi); l'elaborazione richiede personale specializzato (un test ben eseguito e male interpretato e' peggio di una stima prudente).",
 costi_e_economia="Ordini di grandezza indicativi: TRT con sonda pilota dedicata 5-9 k€; TRT su sonda gia' destinata al campo 3-6 k€; il sovradimensionamento prudenziale 'a tabella' su un campo da 20 sonde puo' costare 15-40 k€ inutili: il test si ripaga quasi sempre oltre la piccola taglia.",
 casi_real_world="Caso tipo: scuola con campo da 24 sonde progettato su letteratura (2,0 W/mK presunta); il TRT misura 1,55 W/mK su terreno argilloso asciutto: il progetto viene corretto a 30 sonde prima dell'appalto, evitando un campo che avrebbe perso 2-3 C di sorgente media in cinque anni.",
 normative="Nessuna norma UNI specifica consolidata per il TRT: riferimento alla pratica consolidata internazionale e alle linee guida di settore; i parametri misurati alimentano i calcoli secondo la serie UNI/TS 11300 per le prestazioni energetiche; indagini nel sottosuolo nel rispetto del quadro D.Lgs 152/2006 e delle norme regionali sulle perforazioni.",
 note_cantiere="Pretendi che il TRT sia fatto sulla PRIMA sonda del campo (che poi entra in esercizio), non su un foro separato: misuri la cementazione vera del tuo appaltatore. E la temperatura indisturbata si misura PRIMA di accendere il test, con sonda a riposo da almeno tre giorni: chi la salta falsifica il risultato."
)

add(
 categoria="Scambiatori",
 nome="Sonde geotermiche verticali: perforazione, immissione e cementazione",
 descrizione="La sonda verticale e' lo scambiatore geotermico piu' diffuso: un foro profondo, un circuito in polietilene immerso e una cementazione termoconduttiva che chiude l'intercapedine. Semplice nel concetto, implacabile nell'esecuzione: la qualita' della cementazione decide la resa per i prossimi cinquant'anni.",
 tecnologia="Profondita' tipiche 80-150 m per sonda (oltre servono valutazioni specifiche; molte regioni fissano limiti e procedure per profondita': verificare lo strumento locale); sonda a doppia U in PE100 (tipicamente 4 tubi da 32-40 mm) con testa di fondo, immissione a bobina con pesatura; fluido termovettore: acqua con antigelo (glicole) nei limiti fissati dalle norme di tutela delle acque; cementazione: miscela cementizia-bentonitica termoconduttiva pompata dal fondo verso l'alto (tremie pipe) in continuita', senza interruzioni: i vuoti sono ponti termici verticali e via di comunicazione tra formazioni (vietata); rese tipiche 40-60 W/m di sonda secondo terreno e regime; distanze tra sonde 5-8 m (campi grandi richiedono simulazione di interferenza); collettore orizzontale di testa in pozzetto ispezionabile con bilanciamento delle portate per circuito; verifiche: prova di tenuta in pressione del circuito prima e dopo la cementazione, controllo della lunghezza immersa, documentazione con coordinate e profondita' di ogni sonda.",
 applicazioni="Edifici senza superficie libera sufficiente per collettori orizzontali; terreni con falda utile o roccia a profondita' accessibile; retrofit su aree gia' pavimentate (si perfora dal piazzale); campi da poche sonde (villa) a centinaia (ospedali, quartieri).",
 vantaggi="Superficie occupata minima (qualche m2 a sonda, riutilizzabile sopra); accesso a terreni profondi piu' stabili e spesso piu' conduttivi; sistema chiuso: nessuna concessione idrica in molte regioni (verificare); durata attesa superiore alla vita dell'edificio.",
 limiti="Costo di perforazione dominante; la cementazione male eseguita non e' riparabile (la sonda si perde); interferenza termica tra sonde troppo vicine nei campi grandi; la perforazione attraversa formazioni: serve impresa di perforazione qualificata e piano di gestione fanghi e acque di scavo.",
 costi_e_economia="Ordini di grandezza indicativi: sonda verticale completa (perforazione, sonda PE, cementazione, allaccio) 45-75 €/m in terreni ordinari, di piu' in roccia dura o con rivestimenti; campo di 3 sonde da 100 m per villa: 14-22 k€; pozzetto collettore e bilanciamento 2-5 k€.",
 casi_real_world="Caso tipo: condominio di 24 appartamenti con campo di 12 sonde da 120 m sotto il parcheggio: perforazioni in 3 settimane, cementazione pompata dal fondo con ritorno di miscela al giorno documentato a verbale per ogni sonda; prova di tenuta a 6 bar su ogni circuito prima del collettore; il piazzale ripavimentato sopra il campo.",
 normative="D.Lgs 152/2006 (tutela acque sotterranee: divieto di comunicazione tra acquiferi, fluidi ammessi, aree di salvaguardia); norme regionali su perforazioni e scambiatori geotermici (limiti di profondita', comunicazioni, imprese abilitate: verificare lo strumento locale); D.Lgs 28/2011 per la qualifica FER del sistema.",
 note_cantiere="La cementazione si pompa DAL FONDO e non si ferma finche' la miscela non ritorna pulita in superficie: chi 'riempie dall'alto' lascia vuoti a meta' foro e quella sonda rendera' il 30% in meno per sempre. Verbalizza per OGNI sonda: profondita', sonda immersa, volume di miscela pompato, ritorno, prova di tenuta."
)

add(
 categoria="Scambiatori",
 nome="Collettori orizzontali e trincee: la geotermia di superficie",
 descrizione="Dove c'e' superficie libera e il terreno e' umido, il collettore orizzontale scambia con il primo metro e mezzo di terreno a costi bassissimi: tubi in polietilene posati in trincea o distesi a spirale. E' la geotermia del giardino: economica, ma divoratrice di superficie.",
 tecnologia="Posa a 1,2-2,0 m di profondita' (sotto la fascia geliva e nel terreno a umidita' stabile); layout: serpentina in trincea stretta (passi 30-60 cm), trincea larga con tubi sovrapposti sfalsati, spirali ('slinky') in trincea, geocestelli planari; rese tipiche 15-35 W/m2 di superficie captante secondo umidita' e granulometria del terreno (il terreno asciutto e sabbioso e' il peggiore); superficie richiesta: ordine di 1,5-2,5 volte la superficie riscaldata dell'edificio; vincoli: sopra il collettore niente edifici, pavimentazioni impermeabili, alberi (radici e ombra perturbano), niente compattazione pesante; rigenerazione estiva: il collettore superficiale si rigenera naturalmente con la stagione calda e con l'irraggiamento (e' il suo grande vantaggio termico); allaccio a pozzetto con circuiti bilanciati in lunghezza; protezione da scavi futuri: rete segnaletica e planimetria as-built depositata.",
 applicazioni="Villette con giardino ampio; nuove costruzioni con scavi gia' aperti (il collettore entra nel movimento terra generale); piccoli terziari con aree verdi; integrazione sotto campi sportivi o parcheggi NON pavimentati in modo impermeabile.",
 vantaggi="Costo per kW scambiato il piu' basso tra le tecnologie geotermiche; posa con mezzi da movimento terra ordinari; rigenerazione estiva naturale (il campo 'respira' con le stagioni); nessuna perforazione profonda e relativi adempimenti.",
 limiti="Superficie: il vincolo che esclude la maggior parte dei contesti urbani; resa fortemente dipendente dall'umidita' del terreno (il giardino arido e sabbioso delude); il terreno sopra resta 'servitu' termica' per sempre; piu' sensibile alle stagioni estreme della sonda profonda.",
 costi_e_economia="Ordini di grandezza indicativi: collettore orizzontale posato (scavo, tubi, rinterro, allacci) 20-40 €/m2 di superficie captante; impianto per villa (300-500 m2 di collettore): 8-16 k€ contro 14-22 k€ del campo sonde equivalente; attenzione: la superficie poi non e' edificabile.",
 casi_real_world="Caso tipo: nuova casa unifamiliare con 600 m2 di giardino: collettore a serpentina su 400 m2 posato durante gli scavi di fondazione in una settimana; pompa di calore da 8 kW; il prato sopra il collettore risemina in primavera e dopo due stagioni non si distingue dal resto del giardino.",
 normative="D.Lgs 152/2006 (tutela acque: fluidi ammessi nei circuiti); norme regionali sugli scambiatori geotermici (alcune regioni assimilano i collettori superficiali a opere a bassa invasivita' con adempimenti semplificati: verificare); D.Lgs 28/2011 per la qualifica FER; serie UNI/TS 11300 per le prestazioni.",
 note_cantiere="Posa il collettore a scavo aperto e rinterra con materiale senza pietre, bagnato a strati: l'aria intorno al tubo e' il peggior isolante che puoi regalare al tuo cliente. E tira la rete segnaletica con filo metallico rilevabile: tra dieci anni qualcuno scavera' per una fibra ottica proprio li'."
)

add(
 categoria="Scambiatori",
 nome="Pali energetici e opere di fondazione termoattive: la struttura che climatizza",
 descrizione="Se l'edificio ha bisogno di pali di fondazione, quei pali possono diventare scambiatori geotermici: si immergono circuiti in polietilene nella gabbia d'armatura prima del getto e la fondazione lavora due volte. Il costo marginale e' basso; la progettazione deve essere strutturale E termica insieme.",
 tecnologia="Applicazioni: pali trivellati o infissi in cls con gabbia equipaggiata con anse PE100 fissate all'armatura; diaframmi e paratie termoattivi; platee energetiche (meno diffuse: attenzione ai giunti); rese tipiche 20-40 W/m di palo attrezzato (superficie di scambio grande, temperatura di getto da gestire); accorgimenti di getto: il cls in maturazione sviluppa calore — i primi giorni i circuiti possono smaltirlo (o subirne la pressione termica: circuiti riempiti e monitorati); vincoli strutturali: i tubi non modificano la sezione resistente ma devono sopravvivere al getto e alla vibratura (prove di tenuta prima, durante e dopo); verifica termo-meccanica: i cicli termici inducono tensioni aggiuntive nel palo e nell'interazione terreno-struttura: la letteratura tecnica consolidata mostra effetti gestibili se progettati, ma il dimensionamento termico deve essere coordinato con quello strutturale (responsabilita' condivisa tra geotecnico, strutturista e termotecnico); testata: collettori in pozzetto ispezionabile, circuiti corti e bilanciati; NTC: il palo resta opera strutturale soggetta al quadro delle costruzioni.",
 applicazioni="Edifici urbani su pali (garage interrati, terreni scadenti): il caso in cui le sonde non troverebbero spazio; edifici terziari e direzionali con grandi platee su pali; infrastrutture (gallerie, paratie) con fabbisogni termici vicini.",
 vantaggi="Il terreno 'difficile' diventa risorsa senza perforazioni aggiuntive dedicate; sovraccosto marginale (gabbia gia' necessaria: si aggiungono tubi e fissaggi); ideale dove ogni metro quadro di cantiere e' conteso; i pali sono tanti: campo distribuito e ridondato.",
 limiti="Coordinamento di tre discipline in fase di getto: il punto di fallimento tipico e' organizzativo, non tecnico; la resa per palo e' limitata (servono molti pali: verifica che il fabbisogno sia compatibile); riparabilita' nulla di un circuito danneggiato nel palo (ridondanza di progetto); il collaudo strutturale non copre automaticamente la parte termica: serve documentazione doppia.",
 costi_e_economia="Ordini di grandezza indicativi: sovraccosto dell'attrezzaggio termico sul palo standard 20-40% del costo del palo (tubi, fissaggi, prove, collettori); su un edificio con 100 pali, ordine di 30-80 k€ complessivi contro 60-150 k€ di campo sonde dedicato equivalente — con zero giorni di cantiere aggiuntivi.",
 casi_real_world="Caso tipo: edificio direzionale con due piani interrati su 140 pali trivellati: 120 pali attrezzati con anse PE, prove di tenuta a verbale prima e dopo ogni getto; due circuiti persi in fase di getto (su 120) assorbiti dalla ridondanza; il sistema copre il 70% del fabbisogno invernale dell'edificio dal primo inverno.",
 normative="NTC (D.M. 17/1/2018) per la progettazione strutturale delle fondazioni (il palo termoattivo resta un palo); D.Lgs 152/2006 e norme regionali per gli scambiatori nel sottosuolo; D.Lgs 28/2011 per la qualifica FER; la letteratura tecnica di settore fornisce i criteri di verifica termo-meccanica (non esiste norma UNI specifica consolidata: riferimento alla pratica consolidata e alle linee guida internazionali).",
 note_cantiere="Fissa un verbale di consegna gabbia: armatura finita, anse montate, prova di tenuta fatta, foto PRIMA del getto — e un responsabile del getto che sa che quei tubi esistono. Il palo energetico si perde in dieci secondi di vibratore distratto, e nessuno lo ripara piu'."
)

add(
 categoria="Scambiatori",
 nome="Pozzi di falda (open loop): emungimento e reimmissione dell'acqua di falda",
 descrizione="Il sistema a circuito aperto preleva acqua di falda, la attraversa nello scambiatore della pompa di calore e la reimmette nel medesimo acquifero: la massima efficienza geotermica disponibile, subordinata a portata, autorizzazione e chimica dell'acqua.",
 tecnologia="Schema: pozzo di emungimento -> pompa sommersa -> scambiatore della PdC (acqua-acqua) -> pozzo di reimmissione (o recapito superficiale dove ammesso); salto termico di esercizio tipico 3-5 K: servono portate consistenti (ordine di 0,1-0,15 l/s per kW termico con 4 K di salto); COP elevati (la sorgente e' a 12-16 C e non scende quasi mai); reimmissione nello STESSO acquifero obbligatoria nella pratica autorizzativa ordinaria (non e' uno scarico, e' una restituzione con diverso contenuto termico); criticita' chimico-fisiche: ferro e manganese (ossidano e incrostano lo scambiatore e il pozzo di reiezione: tenere il circuito chiuso all'aria), durezza e incrostazioni, sabbie trascinate (usura pompa e intasamento); pozzo di reimmissione: si intasa nel tempo (clogging biologico e chimico): prevedere contro-lavaggi e, nei progetti seri, la coppia di pozzi interscambiabili; prove: pompaggio di lunga durata con misura di portata e abbassamento, analisi chimica completa PRIMA del progetto; monitoraggio in esercizio: portate, temperature, pressioni e livelli registrati.",
 applicazioni="Edifici di media-grande taglia su acquiferi generosi (terziario, sanitario, produttivo); contesti dove la concessione di derivazione e' ottenibile; sistemi combinati con fabbisogni idrici tecnici (irriguo, industriale) che condividono l'emungimento.",
 vantaggi="COP stagionali tra i piu' alti della climatizzazione (spesso 5-6 di sistema); nessun campo sonde esteso; potenzialita' elevata per singolo punto di presa; l'acqua restituita puo' alimentare anche usi tecnici.",
 limiti="Dipendenza totale da portata e chimica dell'acquifero (i problemi emergono dopo mesi: incrostazioni, cali di portata); iter autorizzativo piu' pesante (concessione di derivazione); il pozzo di reimmissione e' il punto debole storico dei sistemi aperti; vincoli di distanza da pozzi potabili e aree di salvaguardia; responsabilita' termica sull'acquifero (limiti di temperatura alla reimmissione fissati dalle norme).",
 costi_e_economia="Ordini di grandezza indicativi: pozzo di emungimento/reimmissione 5-15 k€ cad. secondo profondita' e diametro; opere idrauliche, scambiatore interposto e automazione 10-30 k€; gestione (contro-lavaggi, manutenzione pompe, monitoraggi) 1-3 k€/anno; a parita' di potenza, capex spesso inferiore al campo sonde oltre i 50-80 kW termici.",
 casi_real_world="Caso tipo: edificio sanitario su acquifero di pianura: coppia di pozzi a 40 m, portata autorizzata 8 l/s, salto termico 4 K per 110 kW termici; circuito intermedio a tenuta d'aria con scambiatore a piastre ispezionabile; contro-lavaggio programmato del pozzo di reimmissione ogni 6 mesi; COP di sistema misurato 5,2 al primo anno.",
 normative="D.Lgs 152/2006 (derivazioni e reimmissioni: concessione, limiti termici e chimici, aree di salvaguardia dei pozzi potabili); norme regionali sulle derivazioni idriche e sugli scambiatori a falda (verificare lo strumento locale); D.Lgs 28/2011 per la qualifica FER; D.M. 37/2008 per la parte impiantistica.",
 note_cantiere="Fai l'analisi chimica dell'acqua PRIMA di firmare il progetto, e se c'e' ferro progetta il circuito senza contatto con l'aria dal primo all'ultimo raccordo: la falda ferrosa incontra l'ossigeno una sola volta e ti regala un pozzo di reimmissione cementato di ossidi. Secondo: progetta i due pozzi interscambiabili, quando puoi: il giorno che la reiezione si intasa, inverti e lavori."
)

add(
 categoria="Impianto",
 nome="La pompa di calore geotermica: selezione, prestazioni e integrazione",
 descrizione="Il cuore del sistema e' una pompa di calore acqua-acqua (o salamoia-acqua): la sorgente stabile le permette prestazioni stagionali che l'aerotermia non raggiunge. Ma la macchina e' solo meta' del sistema: l'altra meta' e' il terminale a bassa temperatura che la fa rendere.",
 tecnologia="Tipologie: salamoia-acqua (circuito chiuso con antigelo lato sorgente) e acqua-acqua (open loop); taglie residenziali tipiche 5-20 kW termici, terziario fino a centinaia di kW anche in cascata; prestazioni: COP di targa a condizioni standard e, quel che conta, SPF (Seasonal Performance Factor) di sistema misurato in esercizio — valori realistici di progetto 4-5 per sistemi ben fatti contro 3-3,5 dell'aerotermia in zone fredde; temperatura di mandata: il COP cresce quando la mandata scende — il radiante a 30-35 C e' il compagno naturale, i radiatori a 55-60 C tagliano le prestazioni e spesso impongono macchine alta temperatura; ACS: produzione con accumulo, gestione antilegionella; desurriscaldatore per ACS gratuita in raffrescamento; regolazione: curva climatica, gestione bivalente con resistenze solo di emergenza (se le resistenze lavorano, il campo e' sottodimensionato o la regolazione sbagliata); monitoraggio: contabilizzazione termica ed elettrica separata per calcolare l'SPF vero.",
 applicazioni="Nuove costruzioni con radiante (matrimonio perfetto); ristrutturazioni con sostituzione terminali o mandata ridotta; terziario e scolastico con fabbisogni bilanciati; edifici NZEB con copertura elettrica da fotovoltaico.",
 vantaggi="SPF superiore e stabile (la sorgente non conosce l'ondata di gelo); nessuno sbrinamento; silenziosita' totale all'esterno; vita macchina lunga (compressore che lavora dolce); raffrescamento attivo a rendimenti elevati e, dove previsto, passivo quasi gratuito.",
 limiti="Il vantaggio si realizza solo con terminali a bassa temperatura: su radiatori esistenti alta temperatura il conto economico spesso crolla; macchina interna (serve locale tecnico); il mercato italiano ha meno installatori esperti rispetto all'aerotermia: la selezione della squadra pesa; costo macchina superiore all'aria-acqua di pari taglia.",
 costi_e_economia="Ordini di grandezza indicativi: pompa di calore geotermica 6-16 kW 700-1.200 €/kW termico di macchina; installazione, accumulo, regolazione e allacci 4-10 k€; SPF 4,5 contro 3,2 dell'aerotermia su 12.000 kWh termici/anno: ordine di 600-900 kWh elettrici risparmiati all'anno.",
 casi_real_world="Caso tipo: ristrutturazione di casa anni '70 con sostituzione dei radiatori con ventilconvettori a bassa temperatura e PdC geotermica da 9 kW su due sonde: mandata invernale 38-42 C, SPF misurato 4,3 al primo anno; le resistenze di emergenza risultano mai entrate in funzione nel monitoraggio.",
 normative="D.Lgs 28/2011 (PdC geotermiche tra le FER: requisiti minimi di prestazione per il riconoscimento); serie UNI/TS 11300 per il calcolo delle prestazioni energetiche; D.M. 37/2008 (installazione impianti); Reg. UE sull'ecodesign dei generatori per i requisiti di immissione sul mercato; UNI EN 14825 per le condizioni di prova delle pompe di calore.",
 note_cantiere="Non far lavorare le resistenze elettriche: imposta il blocco sopra gli 0 C esterni e controlla i consumi del primo inverno. Se il cliente chiama e dice 'la bolletta e' altissima', nove volte su dieci sono le resistenze che suppliscono a un campo sonde tirato: misura l'SPF e guarda il contatore delle integrazioni prima di dare colpe."
)

add(
 categoria="Progettazione",
 nome="Il bilanciamento termico pluriennale: la deriva del terreno e' il vincolo vero",
 descrizione="Un campo geotermico non si dimensiona sulla potenza di punta: si dimensiona sull'energia annua scambiata e sul suo segno. Se estraggo sempre e non restituisco mai, il terreno si raffredda anno dopo anno e il sistema muore lentamente: la deriva termica pluriennale e' il fallimento silenzioso dei campi mal progettati.",
 tecnologia="Bilancio annuo: kWh termici estratti in inverno vs kWh immessi in estate; sbilancio tipico italiano residenziale: dominanza invernale (clima E) o estiva (clima C-D con forte raffrescamento); effetti: temperatura media del campo che scende (o sale) di frazioni di grado l'anno, con accumulo nel tempo: dopo 10-20 anni il COP degrada o la sorgente esce dai limiti macchina; strumenti: simulazione dinamica del campo (software dedicati, pratica consolidata) su 20-30 anni di orizzonte, con profili orari di carico; mitigazioni: (a) sovradimensionamento del campo (costoso); (b) rigenerazione: free cooling estivo che re-immette calore, collettore solare termico dedicato alla ricarica del terreno, scarico estivo su torre evaporativa per i campi a dominanza di raffrescamento; (c) ibridazione: PdC geotermica di base + aerotermia o caldaia di punta (il campo vede solo il carico di base bilanciato); regola pratica: campi con sbilancio oltre il 20-30% vanno ibridati o rigenerati, non ingrossati; monitoraggio: temperatura media del fluido a inizio stagione registrata ogni anno: e' la spia della deriva.",
 applicazioni="Tutti i campi oltre la taglia domestica; edifici a dominanza di raffrescamento (uffici, data room, retail); riqualificazioni dove il carico cambia nel tempo; distretti con campo condiviso.",
 vantaggi="Il progetto bilanciato dura decenni senza degrado; la rigenerazione con free cooling e' quasi gratuita e migliora anche il comfort estivo; l'ibridazione riduce i metri di sonda del 30-50% mantenendo i benefici stagionali sul carico di base.",
 limiti="Richiede profili di carico credibili (spesso stimati: sensibilita' da dichiarare); la simulazione e' specializzata (software e competenze non da installatore medio); la deriva e' lenta: il progettista originale spesso non vede mai le conseguenze dei suoi errori — di qui l'importanza della documentazione e del monitoraggio.",
 costi_e_economia="Ordini di grandezza indicativi: simulazione dinamica del campo con relazione 3-10 k€ secondo taglia; rigenerazione solare dedicata 15-30 €/m2 di collettore; ibridazione che riduce il campo del 40% su campo da 50 sonde: risparmio 90-150 k€ di perforazioni a fronte di 15-30 k€ di macchina di punta.",
 casi_real_world="Caso tipo: edificio per uffici a dominanza estiva (60/40): campo ridotto a 40 sonde con rigenerazione notturna e scarico di punta su dry cooler; simulazione a 25 anni mostra deriva contenuta entro 1,5 C; al quinto anno il monitoraggio conferma le previsioni con scostamento sotto il grado.",
 normative="Serie UNI/TS 11300 per i calcoli energetici; D.Lgs 28/2011 (qualifica FER e obblighi); la progettazione del bilanciamento segue la pratica consolidata internazionale e le linee guida di settore (nessuna norma UNI specifica consolidata sul bilanciamento pluriennale dei campi).",
 note_cantiere="Chiedi sempre il profilo annuo di carico usato nel dimensionamento e la deriva simulata a 20 anni: se il progettista risponde 'abbiamo messo un margine', il campo e' stato indovinato, non progettato. E fai registrare la temperatura di sorgente a inizio stagione ogni anno: cinque righe di tabella che tra dieci anni dicono se il campo sta bene."
)

add(
 categoria="Iter",
 nome="Iter autorizzativo e tutela delle acque sotterranee: prima si verifica, poi si perfora",
 descrizione="La geotermia a bassa entalpia tocca il sottosuolo e spesso le acque: il quadro autorizzativo italiano e' nazionale nei principi (tutela delle acque) e regionale nelle procedure. La parola d'ordine del progettista: verificare lo strumento della PROPRIA regione prima di promettere tempi e costi al committente.",
 tecnologia="Quadro nazionale: D.Lgs 152/2006 (tutela delle acque sotterranee: divieto di immissione di sostanze, protezione degli acquiferi, aree di salvaguardia dei pozzi potabili dove gli scambiatori sono vietati o fortemente limitati); D.Lgs 28/2011 (qualifica FER e semplificazioni); quadro regionale: la maggior parte delle regioni disciplina gli scambiatori geotermici a circuito chiuso con procedure semplificate (comunicazione o SCIA) entro limiti di profondita' e fuori dalle aree sensibili, e riserva autorizzazioni piu' pesanti alle derivazioni di falda (concessione di derivazione idrica per gli open loop); fluidi termovettori: ammessi solo quelli previsti dalle norme di tutela (acqua e miscele con antigelo dichiarate: i fluidi vietati fanno decadere l'autorizzazione e creano responsabilita'); documentazione tipica: progetto geologico-idrogeologico firmato, stratigrafie previste, distanze da pozzi e captazioni (rilievo dei pozzi esistenti nel raggio richiesto dallo strumento), piano di gestione fanghi e acque di perforazione, ripristino; impresa di perforazione: abilitazione secondo le norme regionali sui lavori nel sottosuolo; as-built: deposito delle coordinate e delle stratigrafie reali dove previsto.",
 applicazioni="Qualunque sistema geotermico: la verifica autorizzativa e' la FASE ZERO del progetto; particolare attenzione in aree di salvaguardia, zone SIC/ZPS, aree agricole con pozzi irrigui, siti con contaminazioni note.",
 vantaggi="Le procedure semplificate regionali, dove esistono, rendono il circuito chiuso un iter gestibile in settimane; la documentazione depositata protegge il sistema dagli scavi futuri altrui; la verifica preliminare evita il blocco del cantiere a sonde iniziate.",
 limiti="Disomogeneita' regionale marcata: l'esperienza fatta in una regione non e' trasferibile; le aree di salvaguardia escludono interi comparti (verifica sui vincoli prima dell'offerta); gli open loop hanno iter lunghi e non garantiti; il quadro puo' cambiare: verificare lo strumento vigente alla data del progetto, non quello del progetto precedente.",
 costi_e_economia="Ordini di grandezza indicativi: pratica autorizzativa circuito chiuso semplificato 1,5-4 k€ di tecnico (relazione, rilievi, depositi); concessione di derivazione per open loop 3-8 k€ e tempi di mesi; relazione geologica di supporto 1,5-5 k€; il cantiere bloccato per vincolo non verificato costa molto di piu' di qualunque relazione.",
 casi_real_world="Caso tipo: terziario in zona industriale con due pozzi irrigui nel raggio di verifica: rilievo e mappatura in fase preliminare, campo sonde ridisegnato per rispettare le distanze richieste; comunicazione depositata e cantiere aperto in sei settimane; nessun rilievo dell'ente alle verifiche.",
 normative="D.Lgs 152/2006 (parte III: tutela delle acque dall'inquinamento; aree di salvaguardia); D.Lgs 28/2011 (semplificazioni FER); leggi e regolamenti regionali su scambiatori geotermici e perforazioni del sottosuolo (DA VERIFICARE sullo strumento della regione di intervento: limiti di profondita', procedure, imprese abilitate, distanze); DPR 380/2001 per l'inquadramento edilizio dell'impianto.",
 note_cantiere="Prima di preventivare, fai due telefonate: all'ufficio acque della regione/provincia e al gestore idrico per la mappa delle aree di salvaguardia. Mezza giornata di verifica ti evita di vendere un impianto che non si puo' fare: e nella relazione scrivi data e estremi dello strumento consultato, perche' le norme regionali cambiano."
)

add(
 categoria="Integrazione",
 nome="Geotermia, fotovoltaico e free cooling: l'edificio NZEB che si regge su tre gambe",
 descrizione="La pompa di calore geotermica e' elettrica: accoppiata al fotovoltaico diventa climatizzazione a fonte rinnovabile in loco; accoppiata al free cooling geotermico estivo azzera quasi il consumo di raffrescamento. E' lo schema di riferimento dell'edificio a energia quasi zero.",
 tecnologia="Schema integrato: campo sonde + PdC + terminali radianti (inverno a 30-35 C, estate a 18-20 C con deumidificazione) + fotovoltaico in copertura + accumulo elettrico/termico; free cooling geotermico: d'estate il fluido del campo (12-16 C) circola direttamente nei terminali o in uno scambiatore bypassando il compressore: resta il solo consumo dei circolatori — attenzione alla condensa sui terminali: il free cooling lavora sopra il punto di rugiada (mandata non sotto 16-18 C) o con deumidificazione dedicata; gestione: controllore che ottimizza autoconsumo FV (la PdC lavora nelle ore solari, l'accumulo termico inerziale del radiante fa da batteria termica); obblighi FER: il D.Lgs 28/2011 impone per edifici nuovi e ristrutturazioni rilevanti quote di copertura da rinnovabili dei consumi (ACS, riscaldamento, raffrescamento): lo schema geotermia+FV le copre con margini ampi; contabilizzazione: contatori separati per PdC, FV, usi diversi — servono per la qualifica FER, per gli incentivi e per la diagnosi; CER: lo schema scala a condominio con campo sonde condominiale e ripartizione dei consumi.",
 applicazioni="Nuove costruzioni residenziali e terziarie NZEB; ristrutturazioni profonde con radiante; condomini in riqualificazione con centrale termica comune sostituita da PdC geotermica; edifici scolastici (carichi diurni: FV e PdC lavorano in sincrono).",
 vantaggi="Copertura rinnovabile quasi totale dei consumi di climatizzazione; costi operativi minimi e stabili (indipendenza dal gas); il free cooling riduce drasticamente le ore compressore; massima valorizzazione dell'autoconsumo FV (il caldo d'estate viene dal fresco del terreno, la corrente dal tetto).",
 limiti="Investimento complessivo elevato (tre sistemi insieme: il conto economico va fatto sul ciclo di vita); il free cooling richiede deumidificazione gestita o mandata controllata (progetto idraulico dedicato: non e' un 'accessorio'); complessita' di regolazione: serve un controllore serio e qualcuno che lo sappia programmare; il radiante estivo senza deumidificazione genera condensa e danni.",
 costi_e_economia="Ordini di grandezza indicativi: pacchetto completo villa (campo sonde + PdC 10 kW + radiante esistente + FV 6 kWp + accumulo): 40-60 k€; risparmio annuo vs sistema a gas+split: 1.500-2.500 €/anno secondo prezzi energia; il free cooling toglie tipicamente 300-800 kWh elettrici/anno di raffrescamento attivo.",
 casi_real_world="Caso tipo: scuola primaria riqualificata con 18 sonde, PdC da 60 kW, FV da 45 kWp in copertura e radiante a soffitto: i carichi diurni coincidono con la produzione FV; il primo anno registra autoconsumo dell'82% sulla climatizzazione e raffrescamento estivo per l'80% in free cooling.",
 normative="D.Lgs 28/2011 (obblighi di integrazione FER per edifici nuovi e ristrutturazioni rilevanti: quote di copertura da rinnovabili); D.Lgs 192/2005 e s.m.i. (prestazione energetica degli edifici, NZEB); serie UNI/TS 11300 (calcoli); D.Lgs 199/2021 per eventuale configurazione in CER o autoconsumo collettivo; D.M. 37/2008 per l'installazione.",
 note_cantiere="Il free cooling senza strategia anti-condensa e' un danno annunciato: sensore di punto di rugiada sul collettore e mandata estiva mai sotto il valore di sicurezza, scritto nel piano di regolazione. E collauda le tre modalita' (inverno, estate attiva, free cooling) una per una a verbale: il 'tanto poi si regola da solo' non esiste."
)

add(
 categoria="Economia",
 nome="Conto economico della geotermia: investimento, incentivi e tempi di ritorno",
 descrizione="La geotermia a bassa entalpia si giudica sul ciclo di vita: capex piu' alto dell'aerotermia, opex tra i piu' bassi della climatizzazione, vita degli scambiatori superiore all'edificio. Gli incentivi italiani (Conto Termico e detrazioni) cambiano il tempo di ritorno: vanno applicati con i valori verificati alla data del preventivo.",
 tecnologia="Struttura dei costi: campo scambiatori (sonde 45-75 €/m, collettori 20-40 €/m2, pali +20-40% sul palo, pozzi 5-15 k€ cad.), macchina (700-1.200 €/kW termico), centrale e terminali (radiante 45-80 €/m2 se nuovo), progettazione e indagini (TRT 3-8 k€, autorizzazioni 1,5-8 k€); struttura dei risparmi: SPF 4-5 vs 3-3,5 aerotermia e vs caldaia a gas (confronto in €/kWh termico con i prezzi energia del momento); incentivi (verificare lo stato aggiornato sulle fonti ufficiali: le regole cambiano): Conto Termico 3.0 (D.M. 7/8/2025: pompe di calore, anche geotermiche, tra gli interventi ammessi con contributo percentuale sulle spese ammissibili; plafond e regole in evoluzione: verificare su gse.it), detrazioni fiscali edilizie (aliquote e massimali secondo la legge di bilancio vigente: verificare su agenziaentrate.gov.it); cumulabilita' secondo le regole dei singoli strumenti; confronto con alternative: aerotermia (capex minore, opex maggiore, nessuna autorizzazione di sottosuolo), caldaia a condensazione (capex minimo, opex crescente, prospettiva di phase-out); LCCA: il campo sonde NON si sostituisce alla vita macchina (dura 50+ anni): al secondo compressore il terreno e' ancora li'.",
 applicazioni="Valutazione di fattibilita' in nuove costruzioni e ristrutturazioni; gare con criteri di costo globale (D.Lgs 36/2023 per il pubblico); business plan di ESCO e contratti di prestazione energetica.",
 vantaggi="Opex tra i piu' bassi disponibili e stabile (elettricita' + sorgente gratuita); gli incentivi italiani coprono quote rilevanti del capex quando accessibili; il campo sonde ammortizza su due o tre generazioni di macchine; valore immobiliare (APE alta, nessuna unita' esterna).",
 limiti="Capex iniziale la barriera n.1; tempo di ritorno sensibile ai prezzi dell'energia (gli anni di gas caro lo dimezzano, quelli di energia elettrica cara lo allungano); incentivi variabili e a plafond (il Conto Termico ha gia' sospeso le prenotazioni per eccesso di domanda: mai promettere l'incentivo come certo); su piccole taglie e climi miti l'aerotermia spesso vince il confronto onesto.",
 costi_e_economia="Ordini di grandezza indicativi: impianto residenziale completo chiavi in mano 20-35 k€ (villa) contro 12-18 k€ di aerotermia equivalente; differenza di opex 300-800 €/anno a favore del geotermico; payback della differenza 8-15 anni senza incentivi, 5-9 con incentivi; terziario oltre i 100 kW: il confronto si fa piu' favorevole al geotermico con la taglia.",
 casi_real_world="Caso tipo: banca di terziario di 1.800 m2: confronto LCCA a 20 anni tra aerotermia e geotermia (campo 16 sonde): il geotermico costa 60 k€ in piu' e risparmia 6,5 k€/anno; con il contributo del Conto Termico sul generatore il payback differenziale scende a circa 6 anni e al termine dei 20 anni il vantaggio netto cumulato supera i 70 k€.",
 normative="D.M. 7/8/2025 (Conto Termico 3.0: interventi ammessi, aliquote, regole applicative GSE — verificare lo stato e i plafond su gse.it alla data del preventivo); leggi di bilancio per le detrazioni edilizie (verificare aliquote vigenti su agenziaentrate.gov.it); D.Lgs 28/2011 (qualifica FER); D.Lgs 36/2023 per il costo del ciclo di vita negli appalti pubblici.",
 note_cantiere="Nel preventivo scrivi gli incentivi come 'ipotesi da confermare' con la fonte e la data: il Conto Termico ha gia' chiuso una volta per esaurimento e le detrazioni cambiano ogni dicembre. Chi vende il geotermico promettendo il 65% sicuro compra una causa persa tra due anni."
)

add(
 categoria="Cantiere",
 nome="Perforazione, prove e collaudo: gli errori geotermici si pagano per trent'anni",
 descrizione="Il cantiere geotermico concentra il rischio in poche settimane: perforazioni, cementazioni, allacci, collaudo. Gli errori fatti qui non si vedono in superficie e non si riparano: la difesa e' un protocollo di verifica documentato sonda per sonda, circuito per circuito.",
 tecnologia="Fasi e controlli: (1) tracciamento e verifica interferenze (reti esistenti: SEMPRE ricerca preventiva con strumentazione e scavo di calibratura); (2) perforazione: stratigrafia reale registrata per ogni foro, gestione fanghi e acque secondo piano; (3) immissione sonda: controllo integrita' tubi (prova di pressione prima dell'immissione), pesatura e immissione continua; (4) cementazione: pompata dal fondo in continuita' con ritorno di miscela documentato; (5) prova di tenuta di OGNI circuito in pressione (valore e durata secondo progetto/produttore) dopo cementazione e prima degli allacci; (6) allacci al collettore: saldature PE elettrogiunzione/testa a testa documentate, bilanciamento portate, pozzetto ispezionabile; (7) lavaggio e riempimento con fluido progettato e concentrazione misurata (refrattometro); (8) collaudo: prova di funzionamento con misura di portate e temperature per circuito, verbale con as-built (coordinate, profondita', stratigrafie, prove); errori tipici e conseguenze: distanze ridotte 'per stare nel lotto' (interferenza termica), cementazione a tratti (resa persa), circuiti non lavati (sporcizia nello scambiatore PdC), documentazione mancante (scavi futuri = trapano nella sonda).",
 applicazioni="Ogni installazione geotermica; collaudi di impianti ereditati senza documentazione; perizie su campi sottoperformanti (le prove di tenuta e le temperature per circuito dicono dove cercare).",
 vantaggi="Il protocollo documentato rende il sistema verificabile per tutta la vita (manutenzione, ampliamenti, contenziosi); le prove per singolo circuito isolano i problemi quando sono riparabili; l'as-built depositato protegge il capitale interrato dagli scavi altrui.",
 limiti="Richiede DL e impresa disposti a fermarsi su ogni non conformita' (la pressione del cronoprogramma e' il nemico); le non conformita' scoperte tardi (a collettore chiuso) hanno rimedi costosi; il collaudo 'a impianto acceso e basta' non verifica niente: serve la misura per circuito.",
 costi_e_economia="Ordini di grandezza indicativi: prove di tenuta e verbali per circuito incluse in una posa seria (marginali sul totale); collaudo strumentale con misure per circuito 1-3 k€; la sonda persa per cementazione errata: 4-8 k€ di ri-perforazione piu' i giorni di cantiere; il contenzioso senza verbali: decine di k€ di CTU.",
 casi_real_world="Caso tipo: campo di 20 sonde per edificio scolastico: verbale per sonda con stratigrafia, metri, volume di cementazione, esito prova di tenuta; al collaudo due circuiti mostrano portate anomale: isolati, lavati e ripristinati in due giorni grazie ai pozzetti sezionabili; gli altri 18 circuiti entrano in esercizio con bilanciamento documentato.",
 normative="Norme regionali su perforazioni e scambiatori (adempimenti e depositi: verificare lo strumento locale); D.Lgs 152/2006 (gestione fanghi e acque di perforazione, tutela acquiferi); D.M. 37/2008 (installazione e collaudo impianto); D.Lgs 81/2008 (sicurezza del cantiere di perforazione: rischi di scavo, sollevamento, confinati nei pozzetti); documentazione di collaudo secondo capitolato e pratica consolidata.",
 note_cantiere="Metti nel contratto: verbale per sonda O paghi solo le sonde verbali. E l'ultima foto del cantiere falla al pozzetto collettore aperto con le targhette dei circuiti visibili: quella foto, tra quindici anni, varra' piu' di tutto il capitolato."
)

