p_jsonl = os.path.join(BASE, 'schede', 'schede.jsonl')
out = io.open(p_jsonl, 'w', encoding='utf-8', newline='\n')
for s in S:
    out.write(json.dumps(s, ensure_ascii=False) + '\n')
out.close()

